import{_ as t,o,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"2019-06-12:: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-06-12:: Crimson SeaStor OSD Weekly Meeting","date":"2019-06-12T00:00:00.000Z","updated":"2019-06-13T00:00:00.000Z","tags":["Ceph","分布式存储","Crimson Flavor","测试","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-06-12_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-06-12_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780459816000}'),l={name:"posts/2019/2019-06-12_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function n(s,e,a,_,p,g){return o(),r("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月X日</p><p><strong>参会人员</strong>： Lisa, Sam, Riddick, Robin, Tamara 等</p><p><strong>会议主题</strong>： Ceph分布式存储项目开发讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、Crimson Flavor 新特性</strong></p><ol><li>引入新的 Crimson Flavor，用于病理学安装任务和 CBD 测试，作为性能基准与 CI 中的性能测试进行比较。</li><li>将进行性能测试，使用 Crimson 包验证 PR，并逐步将其纳入夜间测试。</li></ol><p><strong>二、Jenkins 和 Make Check 集成</strong></p><ol><li>使用与 CBT 相同的简单测试集，用于 Jenkins 和 Make Check 的验证。</li><li>需要能够运行低级和崩溃测试，以验证 OSD 功能。</li></ol><p><strong>三、输入缓冲区概念</strong></p><ol><li>推出支持输入缓冲区概念的 RFC 第三版，该概念支持基本对齐和额外部分。</li><li>进行了性能测试，并提供了测试结果。</li></ol><p><strong>四、内存对齐问题</strong></p><ol><li>使用 scatter gather 读取大块数据时，可能会遇到内存对齐问题。</li><li>推出输入缓冲区工厂，以提供更灵活的内存管理，并解决对齐问题。</li></ol><p><strong>五、其他讨论</strong></p><ol><li>讨论了在连接中使用 private 接口的问题，以确保不会滥用该接口。</li><li>讨论了如何正确读取数据段，并确保数据对齐。</li></ol><p><strong>后续行动计划</strong>：</p><ol><li>完成输入缓冲区概念的实现。</li><li>更新安装任务，以使用 Crimson Flavor。</li><li>完成性能测试，并逐步将其纳入夜间测试。</li><li>完成RFC第三版的审查和反馈。</li></ol><p><strong>备注</strong>：</p><ul><li>会议中提到了一些计算机科学/ceph相关领域英文原文的关键词，如：Crimson Flavor、performance testing、input buffer factory、scatter gather、private interface 等。</li><li>会议讨论的内容涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</li></ul>',19)])])}const S=t(l,[["render",n]]);export{m as __pageData,S as default};
